import {safety,nextPremium,monthInvestment,tradeProfit} from './finance.js';
import {readMeta,summary,writeMeta,localCheckpoint,localVersions,unpackBackup} from './storage.js';
import {csvFiles} from './csv.js';
const localMeta=readMeta();let startupMutated=false;
import {editCategory,mergeCategory,removeCategory,restoreCategory} from './categories.js';
import {prepareExpenseState,categoryActive,followingMonth,validateRecurring} from './recurring.js';
import {nextMonth,quoteSymbol,allocationAnalysis,validateInvestmentPlan} from './planner.js';

import {monthSpending,spendingChange} from './comparison.js';
import {normalisePortfolio,portfolioTotals,updateHolding,validatePortfolio,validateHistory} from './investments.js';
import {KEY,today,money,uid,amount,blank,budget,stats,available,saveTransaction,deleteTransaction,validate} from './model.js';
const $=s=>document.querySelector(s), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const defaults=await fetch('./defaults.json').then(r=>r.json());
let state,revision=null,storageBroken=false,month=today().slice(0,7),view='home',search='',filter='',reviewOnly=false,categoryFilter='';
try{const raw=localStorage.getItem(KEY);state=raw?validate(JSON.parse(raw)):blank(defaults);revision=raw}catch(e){storageBroken=true;state=blank(defaults);}
if(!storageBroken){try{const next=prepareExpenseState(state,today());validate(next);const raw=JSON.stringify(next);if(raw!==revision){startupMutated=true;if(localStorage.getItem(KEY)!==revision)throw Error('帳本喺另一視窗有更新');localStorage.setItem(KEY,raw);revision=raw;}state=next}catch(e){storageBroken=true}}
const nav=[['home','◫','每日'],['budgets','▥','預算'],['goals','◎','儲錢'],['investments','◈','投資'],['ledger','≡','明細'],['review','✓','月尾'],['settings','⚙','設定']];
const colours=['#7aa59b','#a4b97b','#d6ad80','#8dbbc8','#baa3c8','#d6a499'];
const glyphs={'美食':'◌','餐飲':'◌','服飾裝扮':'◇','車輛交通':'↗','娛樂休閑':'✧','日用百貨':'▧','租屋/租車位':'⌂','信用卡':'▱','電話費':'▯','保費':'⊕','家用':'⌂','醫療健康':'＋'};
const payments={'MPay 綁定銀行':'bank','MPay 餘額':'mpay','MPay 綁定信用卡':'card','信用卡':'card','銀行轉帳':'bank','現金':'cash'};
const cat=id=>state.categories.find(c=>c.id===id), account=id=>state.accounts.find(a=>a.id===id), moneyText=n=>'MOP '+money(n), pct=(v,total)=>total>0?Math.max(0,Math.min(100,v/total*100)):0;
const progress=(v,total)=>`<div class="progress ${v>total?'over':''}" role="meter" aria-label="已使用 ${money(v)}，目標 ${money(total)}" aria-valuemin="0" aria-valuemax="${Math.max(total,1)}" aria-valuenow="${Math.min(v,Math.max(total,1))}"><i style="width:${pct(v,total)}%"></i></div>`;
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),4000)}
function commit(next){next=prepareExpenseState(next,today());validate(next);if(storageBroken)throw Error('本機資料未能讀取。請先去設定匯出原始資料，再還原有效備份。');const current=localStorage.getItem(KEY);if(current!==revision)throw Error('另一個視窗改咗帳本。請重新載入，再試一次。');const raw=JSON.stringify(next);try{localStorage.setItem(KEY,raw)}catch{throw Error('未能儲存，可能空間不足或使用緊私密瀏覽。請先匯出備份，呢次修改未有儲存。')}state=next;revision=raw;render()}
window.addEventListener('storage',e=>{if(e.key===KEY)toast('另一個視窗更新咗帳本，請重新載入。')});
function modal(title,body,onSubmit){$('#modal-content').innerHTML=`<div class="modal-head"><h2 id="modal-title">${esc(title)}</h2><button class="icon-button" data-close aria-label="關閉">×</button></div>${body}`;$('#modal-content').querySelector('[data-close]').onclick=()=>$('#modal').close();const f=$('#modal-content form');if(f)f.onsubmit=async e=>{e.preventDefault();const submit=f.querySelector('[type=submit]');if(submit)submit.disabled=true;try{await onSubmit(new FormData(f))}catch(err){let el=$('#form-error');if(el)el.textContent=err.message;else toast(err.message)}finally{if(submit)submit.disabled=false}};if(!$('#modal').open)$('#modal').showModal();}
const actions=(label='儲存')=>`<p id="form-error" class="error" role="alert"></p><div class="actions"><button type="button" class="btn quiet" onclick="document.querySelector('#modal').close()">取消</button><button class="btn primary" type="submit">${label}</button></div>`;
const field=(label,content,full=false)=>`<label class="field ${full?'full':''}">${label}${content}</label>`;
const input=(name,value='',type='text',extra='')=>`<input name="${name}" type="${type}" value="${esc(value)}" ${extra}>`;
const opt=(v,label,selected)=>`<option value="${esc(v)}" ${v===selected?'selected':''}>${esc(label)}</option>`;
const pageHead=(eyebrow,title,right='')=>`<section class="page-head"><div><p class="eyebrow">${eyebrow}</p><h1>${title}</h1></div>${right}</section>`;
function render(){view=nav.some(x=>x[0]===location.hash.slice(1))?location.hash.slice(1):'home';$('#month').value=month;$('#page-label').textContent=nav.find(x=>x[0]===view)[2];document.querySelectorAll('#side-nav,#bottom-nav').forEach(el=>el.innerHTML=nav.filter(x=>el.id!=='bottom-nav'||!['goals','ledger'].includes(x[0])).map(([id,icon,label])=>`<a class="nav-item ${id===view?'active':''}" href="#${id}" ${id===view?'aria-current="page"':''}><span class="nav-icon" aria-hidden="true">${icon}</span>${label}</a>`).join(''));$('#app').innerHTML=(storageBroken?'<div class="notice">未能讀取本機帳本，請去設定備份原始資料。暫停儲存以保護原有記錄。</div>':'')+({home:home,budgets:budgets,goals:goals,investments:investments,ledger:ledger,review:review,settings:settings}[view])();bind();}
function pocket(c,i,st){const b=budget(state,c,month),used=st.byCategory[c.id]??0,left=b-used;return `<button class="pocket" data-new-category="${c.id}" style="--pocket-color:${colours[i%6]};--fill:${pct(Math.max(0,left),b)}%"><div class="pocket-head"><span>${esc(c.name)}</span><span class="pocket-icon">${glyphs[c.name]||'◈'}</span></div><div class="remaining ${left<0?'negative':''}">${left<0?'超出 ':'剩 '}${money(Math.abs(left))}</div><div class="small">已用 ${money(used)} ／ ${money(b)}</div></button>`}
function monthlyPlan(st){const target=state.categories.filter(c=>c.type==='投資/儲蓄'&&c.name!=='現金儲蓄').reduce((n,c)=>n+budget(state,c,month),0);return `<section class="panel"><div class="section-title"><h3>每月投資／儲蓄</h3><a class="link" href="#goals">睇進度 ↗</a></div><div class="row"><div><p class="micro">${esc(month)} 已轉出</p><div class="stat">${money(st.invest)}</div><small class="muted">目標 ${moneyText(target)}</small></div><div class="goal-ring" style="--pct:${pct(st.invest,target)}%" data-label="${Math.round(pct(st.invest,target))}%"></div></div>${progress(st.invest,target)}<p class="small muted">${target===0?'先喺預算設定每月目標。':target>st.invest?'仲差 '+moneyText(target-st.invest):'今個月嘅目標已完成。'}</p></section>`}
function budgets(){const st=stats(state,month);return pageHead('A PLACE FOR EVERY DOLLAR','分類預算。','<a class="btn" href="#review">月尾工具 ↗</a>')+`<p class="muted small">調整只影響 ${esc(month)}；原有月份預算會保留。支出依主分類計入預算袋。</p>`+['必要支出','想要支出','投資/儲蓄','收入'].map(type=>`<h2 class="group-label">${type}</h2><div class="budget-list">${state.categories.filter(c=>c.type===type&&(!c.archivedFrom||month<c.archivedFrom.slice(0,7)||(st.byCategory[c.id]||0)>0)).map((c,i)=>{const b=budget(state,c,month),v=st.byCategory[c.id]||0;return `<section class="budget-row" style="--category-color:${colours[i%6]}"><div class="row"><h3>${esc(c.name)}${c.archivedFrom?'<span class="tag">已停用</span>':c.fixed?'<span class="tag">固定</span>':''}</h3><div><button class="link" data-budget="${c.id}">改預算</button></div></div>${progress(v,b)}<div class="row small"><span class="muted">${type==='收入'?'已收到':type==='投資/儲蓄'?'已轉出':'已用'} ${money(v)} ／ ${money(b)}</span><span class="${v>b&&type.includes('支出')?'negative':''}">${v>b?'超出 ':'尚餘 '}${money(Math.abs(b-v))}</span></div><div class="row" style="margin-top:8px"><button class="link" data-category-ledger="${c.id}">睇明細</button>${categoryActive(c,today())?`<button class="link" data-new-category="${c.id}">＋ 記一筆</button>`:''}</div></section>`}).join('')}</div>`).join('')}
function goals(){const st=stats(state,month),av=available(state);return pageHead('SAVE FOR WHAT MATTERS','留畀未來嘅自己。','<button class="btn primary" data-new-goal>＋ 新目標</button>')+`<div class="layout"><div class="stack">${spendingComparison()}${monthlyPlan(st)}<div class="notice info">「儲錢目標」只係將現有現金留起，唔會轉走錢。已留起金額會從真正可用金額扣除；每月投資轉出另外計，唔會重複扣。</div></div><section class="panel"><p class="muted small">目標儲蓄合計</p><div class="stat">${moneyText(av.saved)}</div><p class="small muted" style="margin-top:12px">可以用嚟儲應急錢、旅行費，或者預留下一期保費。</p></section></div><div class="goal-cards" style="margin-top:24px">${state.goals.map(g=>`<section class="goal-card"><div class="row"><h3>${esc(g.name)}</h3><button class="link" data-edit-goal="${g.id}">修改</button></div><p class="micro">${g.deadline?'目標日期 '+esc(g.deadline):'按自己節奏儲'}</p><div class="stat">${money(g.saved)} <small class="muted" style="font-size:14px">／ ${money(g.target)}</small></div>${progress(g.saved,g.target)}<div class="row small"><span class="muted">${g.saved>=g.target?'目標完成！':'仲差 '+moneyText(g.target-g.saved)}</span><button class="btn" data-reserve="${g.id}">留起／取回</button></div></section>`).join('')||'<section class="panel full empty"><div class="empty-icon">◎</div><h3>第一個目標，想為乜而儲？</h3><p>設定目標金額，再慢慢留起。</p><button class="btn" data-new-goal>建立儲錢目標</button></section>'}</div>`}
function transactionRow(t){const c=cat(t.categoryId);const title=t.kind==='transfer'?'帳戶轉帳':t.kind==='repay'?'信用卡還款':c?.name||t.type;return `<button class="transaction" data-edit-tx="${t.id}"><span class="transaction-icon">${t.kind==='income'?'＋':t.kind==='transfer'||t.kind==='repay'?'⇄':glyphs[title]||'◇'}</span><span class="transaction-body"><p>${esc(t.note||title)}${t.estimated?'<span class="tag">預填・待核對</span>':t.review?'<span class="tag">待核對</span>':''}</p><span class="micro">${esc(t.date)} · ${esc(title)} · ${esc(t.payment)}</span></span><span class="transaction-amount ${t.kind==='income'?'positive':''}">${t.kind==='income'?'+':t.kind==='expense'||t.kind==='invest'?'−':''}${money(t.amount)}</span></button>`}
function ledger(){const st=stats(state,month);return pageHead('EVERY LITTLE THING','每一筆，都有跡可尋。','<button class="btn" data-csv>匯出 CSV</button>')+`<div class="filters"><input id="search" type="search" placeholder="搵備註、分類或付款方式" aria-label="搜尋交易" value="${esc(search)}"><select id="type-filter" aria-label="交易類型">${opt('','全部類型',filter)}${['必要支出','想要支出','收入','投資/儲蓄','帳戶轉帳','信用卡還款'].map(v=>opt(v,v,filter)).join('')}</select><button class="btn ${reviewOnly?'primary':''}" id="review-filter">待核對 ${state.transactions.filter(t=>t.review).length}</button></div>${categoryFilter?`<p class="small">分類：${esc(cat(categoryFilter)?.name)} <button class="link" id="clear-category">清除篩選</button></p>`:''}<div class="grid-3"><div class="metric"><span class="micro">本月收入</span><strong>${money(st.income)}</strong></div><div class="metric"><span class="micro">生活支出</span><strong>${money(st.expense)}</strong></div><div class="metric"><span class="micro">記帳結餘</span><strong class="${st.flow<0?'negative':''}">${money(st.flow)}</strong></div></div><section class="panel" style="margin-top:20px"><div id="ledger-rows"></div></section><section class="panel" style="margin-top:20px"><div class="section-title"><h3>月結</h3><span class="micro">由流水重新計算</span></div><div class="table-wrap"><table><thead><tr><th>月份</th><th>收入</th><th>生活支出</th><th>投資／儲蓄</th><th>結餘</th></tr></thead><tbody>${[...new Set(state.transactions.map(t=>t.date.slice(0,7)))].sort().reverse().map(m=>{const v=stats(state,m);return `<tr><td><button class="link" data-month="${m}">${m}</button></td><td>${money(v.income)}</td><td>${money(v.expense)}</td><td>${money(v.invest)}</td><td class="${v.flow<0?'negative':''}">${money(v.flow)}</td></tr>`}).join('')}</tbody></table></div></section>`}
function ledgerRows(){const ts=state.transactions.filter(t=>(reviewOnly?t.review:t.date.startsWith(month))&&(!filter||t.type===filter)&&(!categoryFilter||t.categoryId===categoryFilter)&&[t.note,cat(t.categoryId)?.name,t.payment].join(' ').toLowerCase().includes(search.toLowerCase())).sort((a,b)=>b.date.localeCompare(a.date));$('#ledger-rows').innerHTML=(reviewOnly?'<p class="small muted">待核對會顯示所有月份。舊帳數字會保留，直至你自行確認或修改。</p>':'')+ts.map(transactionRow).join('')+(ts.length?'':'<div class="empty">搵唔到符合條件嘅交易。</div>');$('#ledger-rows').querySelectorAll('[data-edit-tx]').forEach(b=>b.onclick=()=>transactionForm(b.dataset.editTx));}
function portfolioView(){const p=state.portfolio;if(!p)return `<section class="panel"><h3>股票同投資資產</h3><p class="small muted" style="margin-top:12px">獨立記錄持倉、價格同投資進度。</p><a class="btn" href="#investments">開啟投資總覽 ↗</a></section>`;const total=portfolioTotals(p);return `<section class="panel"><div class="section-title"><h3>股票同投資資產</h3><span class="pill">唔計入可用錢</span></div><div class="stat">${moneyText(total.valueMOP)}</div><p class="small muted" style="margin-top:10px">按已記錄價格計算 · 非即時報價</p><a class="link" href="#investments">持倉、價格、快照 ↗</a></section>`}
function transactionForm(id=null,categoryId=null,kindOverride=null){
 const old=state.transactions.find(t=>t.id===id),chosen=cat(categoryId)||cat(old?.categoryId)||state.categories.find(c=>c.name==='美食')||state.categories[0];
 if(!old && !kindOverride && chosen.name==='現金儲蓄'){goalForm();toast('仍留喺銀行嘅儲蓄，用目標留起就得，唔使記成轉出。');return}
 const kind=kindOverride||old?.kind||(chosen.type==='收入'?'income':chosen.type==='投資/儲蓄'?'invest':'expense');
 const types=[['expense','日常支出'],['income','收入'],['invest','轉到投資／外部儲蓄戶口'],['transfer','帳戶轉帳'],['repay','信用卡還款']];
 const apply=old?old.effects.length>0:available(state).ready;
 modal(old?'修改呢筆記錄':'記一筆',`${old?.estimated?'<p class="notice info">呢筆係固定開支預填。改金額只影響呢筆；確認付款時可以剔選更新帳戶餘額，再標示已核對。</p>':''}<form><div class="form-grid">${field('金額 · MOP',input('amount',old?money(old.amount).replaceAll(',',''):'','text','required inputmode="decimal" placeholder="0.00" class="amount-input"'),true)}${field('日期',input('date',old?.date||today(),'date','required'))}${field('記錄類型',`<select name="kind">${types.map(([v,n])=>opt(v,n,kind)).join('')}</select>`)}<div id="dynamic-fields" class="full form-grid"></div>${field('備註',input('note',old?.note||'','text','maxlength="3000" placeholder="例如：午餐、超市"'),true)}</div><div id="entry-preview" class="inline-preview"></div><label class="check" style="margin-top:16px"><input name="apply" type="checkbox" ${apply?'checked':''}><span>更新目前帳戶餘額<br><span class="micro">補記核對餘額之前嘅交易，唔好剔選。舊帳預設唔更新餘額。</span></span></label>${old?.review?'<label class="check" style="margin-top:12px"><input type="checkbox" name="reviewed"><span>我已核對：呢筆係消費定還款，分類及類型亦正確。</span></label>':''}${actions(old?'儲存修改':'記下')}${old?'<button type="button" class="link negative" id="delete-tx">刪除呢筆</button>':''}</form>`,f=>{
  const k=f.get('kind'),c=cat(f.get('category')),value=amount(f.get('amount'));if(old?.insuranceCycle&&k!=='expense')throw Error('保費付款必須保持支出類型；如要取消，請刪除呢筆付款。');if(value<=0)throw Error('金額要大過 0。');const d=f.get('date');if(c&&!categoryActive(c,today())&&old?.categoryId!==c.id)throw Error('呢個分類已停用，請選其他分類。');if(d>today())throw Error('未來嘅交易請到當日先記帳。');
  const payment=f.get('payment')||'銀行轉帳';const source=['transfer','repay'].includes(k)?f.get('source'):payments[payment]||old?.accountId||'bank';
  let type=k==='income'?'收入':k==='invest'?'投資/儲蓄':k==='transfer'?'帳戶轉帳':k==='repay'?'信用卡還款':f.get('expenseType');
  const t={id:old?.id||uid(),date:d,type,kind:k,categoryId:c?.id||null,amount:value,payment,accountId:source,toAccountId:k==='repay'?'card':f.get('target')||null,note:String(f.get('note')).trim(),imported:old?.imported||false,review:old?.review&&!f.get('reviewed')||false,estimated:!!old?.estimated&&!f.get('reviewed'),...(old?.insuranceCycle?{insuranceCycle:old.insuranceCycle}:{}),...(old?.recurringId?{recurringId:old.recurringId,recurringKey:old.recurringKey}:{}),effects:[]};
  commit(saveTransaction(state,t,!!f.get('apply')));$('#modal').close();toast('已記低，預算已更新。');
 });
 const form=$('#modal-content form');
 function dynamic(){const k=form.elements.kind.value;const categories=state.categories.filter(c=>categoryActive(c,today())||old?.categoryId===c.id).filter(c=>k==='income'?c.type==='收入':k==='invest'?(c.type==='投資/儲蓄'&&(c.name!=='現金儲蓄'||old?.categoryId===c.id)):c.type.includes('支出'));const selected=categories.some(c=>c.id===chosen.id)?chosen.id:categories[0]?.id;
  $('#dynamic-fields').innerHTML=['transfer','repay'].includes(k)?`${field('由邊個帳戶扣',`<select name="source">${state.accounts.filter(a=>a.type==='asset').map(a=>opt(a.id,a.name,old?.accountId||'bank')).join('')}</select>`)}${k==='transfer'?field('轉去邊個帳戶',`<select name="target">${state.accounts.filter(a=>a.type==='asset').map(a=>opt(a.id,a.name,old?.toAccountId||'mpay')).join('')}</select>`):'<p class="small muted">還款至信用卡，唔計入生活支出。</p>'}`:
   `${field('主分類',`<select name="category">${categories.map(c=>opt(c.id,c.name,selected)).join('')}</select>`)}${field('付款／收款方式',`<select name="payment">${Object.keys(payments).filter(p=>k==='expense'||!p.includes('信用卡')).map(p=>opt(p,p,old?.payment||state.settings.defaultPayment)).join('')}${old?.payment&&!payments[old.payment]?opt(old.payment,old.payment,old.payment):''}</select>`)}${k==='expense'?field('支出類型',`<select name="expenseType">${['必要支出','想要支出'].map(v=>opt(v,v,old?.type||cat(selected)?.type)).join('')}</select>`,true):''}`;
  if(form.elements.category)form.elements.category.onchange=()=>{if(form.elements.expenseType)form.elements.expenseType.value=cat(form.elements.category.value).type;preview()};
  preview();
 }
 function preview(){let n;try{n=amount(form.elements.amount.value||'0')}catch{$('#entry-preview').textContent='輸入金額後會預覽預算餘額。';return}const k=form.elements.kind.value;const c=cat(form.elements.category?.value),m=form.elements.date.value.slice(0,7);if(c){const st=stats(state,m);let used=st.byCategory[c.id]||0;if(old?.categoryId===c.id&&old.date.startsWith(m))used-=old.amount;const left=budget(state,c,m)-used-n;$('#entry-preview').textContent=(k==='expense'?c.name+'：記低之後'+(left<0?'超支 ':'仲剩 ')+moneyText(Math.abs(left)):'呢筆會計入 '+m+' 嘅'+(k==='income'?'收入':'投資／儲蓄轉出（仍留喺銀行嘅儲蓄請用目標留起）'))}else $('#entry-preview').textContent='只改帳戶餘額，唔會扣分類預算。';if(!old&&c&&state.transactions.some(t=>t.estimated&&t.categoryId===c.id&&t.date.startsWith(m)))$('#entry-preview').textContent+=' 提提你：呢個月已有同類預填，請先去明細核對，避免重複記帳。';}
 form.elements.kind.onchange=dynamic;form.addEventListener('input',preview);dynamic();
 if(old)$('#delete-tx').onclick=()=>modal('刪除呢筆記錄？',`<p class="muted">${esc(old.date)} · ${moneyText(old.amount)}<br>會同時還原呢筆仍然生效嘅帳戶變動。</p><form>${actions('確定刪除')}</form>`,()=>{commit(deleteTransaction(state,old.id));$('#modal').close();toast('已刪除。')});
}
function accountsForm(){modal('核對目前餘額',`<p class="small muted">填而家見到嘅實際餘額，已包括過往所有交易。銀行同卡數可以填合計；冇用嘅帳戶填 0。</p><form><div class="form-grid">${state.accounts.map(a=>field(a.type==='debt'?'信用卡未還總額':esc(a.name)+'合計',input(a.id,a.balance===null?'':(a.balance/100).toFixed(2),'text','required inputmode="decimal" placeholder="0.00"'))).join('')}</div><p class="micro" style="margin-top:15px">核對後，舊記錄唔會再自動改動呢個新餘額；之後新記嘅交易先會扣數。</p>${actions('確認目前餘額')}</form>`,f=>{const n=structuredClone(state);for(const a of n.accounts)a.balance=amount(f.get(a.id));n.settings.balanceAsOf=today();for(const t of n.transactions)t.effects=[];commit(n);$('#modal').close();toast('餘額已核對，可以開始記帳。')})}
function budgetForm(id){const c=cat(id);modal('調整 '+c.name,`<p class="small muted">只更新 ${esc(month)} 嘅預算，唔會改過去月份。</p><form>${field('月預算 · MOP',input('budget',(budget(state,c,month)/100).toFixed(2),'text','required inputmode="decimal"'))}${actions()}</form>`,f=>{const n=structuredClone(state);n.budgetOverrides[month]={...n.budgetOverrides[month],[id]:amount(f.get('budget'))};commit(n);$('#modal').close();toast('呢個月預算已更新。')})}
function categoryForm(id){const c=cat(id);modal('修改分類',`<p class="small muted">改名會同時顯示喺舊記錄同歷史比較；交易金額、備註同帳戶餘額保持不變。「固定」係分類標示，自動預填請另外設定固定開支。</p><form>${field('分類名稱',input('name',c.name,'text','required maxlength="40"'))}<label class="check"><input name="fixed" type="checkbox" ${c.fixed?'checked':''}><span>固定開支</span></label>${actions('儲存分類')}</form>${!c.archivedFrom?'<button class="link" id="merge-category">合併到其他分類</button> <button class="link negative" id="remove-category">移除分類</button>':''}`,f=>{commit(editCategory(state,id,f.get('name'),!!f.get('fixed')));$('#modal').close();toast('分類已更新。')});if($('#merge-category'))$('#merge-category').onclick=()=>mergeCategoryForm(id);if($('#remove-category'))$('#remove-category').onclick=()=>removeCategoryForm(id)}
function removeCategoryForm(id){const c=cat(id),count=state.transactions.filter(t=>t.categoryId===id).length;modal('移除 '+c.name,`<p>呢個分類共有 ${count} 筆流水記錄。</p><p class="small muted">移除後唔再供新增記帳選用，由本月起預算為 0，相關自動預填亦會暫停。舊記錄、帳戶餘額同儲錢目標會保留；有交易嘅月份仍會顯示歷史數字。</p><p class="small muted">之後可以喺「舊分類同歷史記錄」還原分類，原有預算同自動預填設定會恢復。</p><form>${actions('移除分類')}</form>`,()=>{commit(removeCategory(state,id,today()));$('#modal').close();toast('分類已移除，可喺舊分類同歷史記錄還原。')})}
function mergeCategoryForm(id){const c=cat(id),targets=state.categories.filter(x=>x.id!==id&&x.type===c.type&&!x.archivedFrom);modal('合併 '+c.name,`<p class="small muted">將呢個分類嘅所有交易、固定開支範本同歷史參考移去所選分類，兩個分類嘅預算會相加。交易金額、備註、帳戶餘額同預填紀錄保持不變；完成後移除原分類。</p><form>${field('合併到',`<select name="target" required>${targets.map(x=>opt(x.id,x.name,'')).join('')}</select>`)}${actions('合併分類')}</form>`,f=>{commit(mergeCategory(state,id,f.get('target')));categoryFilter='';$('#modal').close();toast('分類已合併。')})}
function newCategory(){modal('新增分類',`<form><div class="form-grid">${field('分類名稱',input('name','','text','required maxlength="40"'),true)}${field('類型',`<select name="type">${['必要支出','想要支出','收入','投資/儲蓄'].map(v=>opt(v,v,'想要支出')).join('')}</select>`)}${field('預設月預算 · MOP',input('budget','0','text','required inputmode="decimal"'))}</div>${actions()}</form>`,f=>{const name=String(f.get('name')).trim();if(!name)throw Error('請填分類名稱。');if(name==='信用卡')throw Error('信用卡請用付款方式，再按實際用途分類。');if(state.categories.some(c=>c.name===name))throw Error('已有同名分類。');const n=structuredClone(state);n.categories.push({id:uid(),name,type:f.get('type'),budget:amount(f.get('budget')),fixed:false});commit(n);$('#modal').close();toast('分類已加入。')})}
function goalForm(id=null){const g=state.goals.find(g=>g.id===id);modal(g?'修改儲錢目標':'新嘅儲錢目標',`<form><div class="form-grid">${field('目標名稱',input('name',g?.name||'','text','required maxlength="60" placeholder="例如：應急錢"'),true)}${field('目標金額 · MOP',input('target',g?g.target/100:'','text','required inputmode="decimal"'))}${field('目標日期（可留空）',input('deadline',g?.deadline||'','date'))}</div><p class="small muted" style="margin-top:15px">先定目標，再撳「留起／取回」分配現有嘅錢。</p>${actions(g?'儲存修改':'建立目標')}${g?'<button type="button" class="link negative" id="delete-goal">刪除目標並釋放已留起金額</button>':''}</form>`,f=>{const target=amount(f.get('target')),name=String(f.get('name')).trim();if(!name)throw Error('請填目標名稱。');if(target<=0||target<(g?.saved||0))throw Error('目標要大過 0，而且唔可以少過已留起金額。');const n=structuredClone(state);const goal={id:g?.id||uid(),name,target,saved:g?.saved||0,deadline:f.get('deadline')};n.goals=n.goals.filter(x=>x.id!==goal.id);n.goals.push(goal);commit(n);$('#modal').close();toast('目標已儲存。')});if(g)$('#delete-goal').onclick=()=>modal('刪除呢個目標？',`<p class="muted">${esc(g.name)} 已留起嘅 ${moneyText(g.saved)} 會重新計入可用金額。現金帳戶餘額唔會改變。</p><form>${actions('刪除目標')}</form>`,()=>{const n=structuredClone(state);n.goals=n.goals.filter(x=>x.id!==g.id);commit(n);$('#modal').close();toast('目標已刪除，已留起金額已釋放。')})}
function reserveForm(id){const g=state.goals.find(g=>g.id===id),av=available(state);modal(g.name+' · 留起／取回',`<p class="small muted">已留起 ${moneyText(g.saved)}。只改用途分配，唔會搬走銀行入面嘅錢。</p><form><div class="form-grid">${field('操作',`<select name="direction"><option value="add">留起更多</option><option value="remove">取回可用金額</option></select>`)}${field('金額 · MOP',input('amount','','text','required inputmode="decimal"'))}</div><p class="small muted" style="margin-top:12px">目前可用：${av.ready?moneyText(av.value):'先去設定核對帳戶餘額'}</p>${actions('確認分配')}</form>`,f=>{const a=amount(f.get('amount')),add=f.get('direction')==='add';if(a<=0)throw Error('金額要大過 0。');if(add&&!av.ready)throw Error('請先核對帳戶餘額。');if(add&&a>Math.max(av.value,0))throw Error('留起金額唔可以多過目前可用金額。');if(add&&g.saved+a>g.target)throw Error('超過目標金額，可以先調高目標。');if(!add&&a>g.saved)throw Error('取回金額多過已留起金額。');const n=structuredClone(state);n.goals.find(x=>x.id===id).saved+=add?a:-a;commit(n);$('#modal').close();toast(add?'已幫你留起呢筆錢。':'已重新計入可用金額。')})}
function download(name,content,type){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000)}
function csvExport(){const files=csvFiles(state);modal('匯出 CSV 報表',`<p class="small muted">每份報表包括全部已記錄月份，支援 Excel／Numbers。CSV 唔係完整還原檔；換機請另外下載 JSON 完整備份。</p><div class="settings-list">${files.map((f,i)=>`<button class="btn" data-csv-file="${i}">${esc(f.label)} ↓</button>`).join('')}</div><p class="micro">逐份下載後，確認已儲存到「檔案」。金額欄會標示幣別，持倉估值係按你最後填寫嘅價格。</p>`);$('#modal-content').querySelectorAll('[data-csv-file]').forEach(b=>b.onclick=()=>{const f=files[+b.dataset.csvFile];download('記賬-'+f.label+'-'+today()+'.csv',f.content,'text/csv;charset=utf-8');localMeta.lastCsvExport=new Date().toISOString();writeMeta(localMeta);toast('已發起下載，請確認 CSV 已儲存。')})}
function backup(){try{const exportedAt=new Date().toISOString();download('記賬-備份-'+today()+'.json',JSON.stringify({format:'ledger-backup-v2',exportedAt,ledger:state},null,2),'application/json');localMeta.lastExport=exportedAt;writeMeta(localMeta);render();toast('已發起下載，請確認已存入「檔案」→「我的 iPhone」。')}catch(e){toast(e.message)}}
$('#import-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>20000000)throw Error('請選小於 20MB 嘅備份。');const b=unpackBackup(await file.text());await restorePreview(b.state,b.createdAt,file.name)}catch(err){toast('未能匯入：'+err.message)}finally{e.target.value=''}};

function help(){modal('加到 iPhone 主畫面',`<ol class="small"><li>喺 iPhone 用 Safari 打開已發佈嘅網址。</li><li>撳「分享」→「加入主畫面」。</li><li>如果有「以網頁 App 開啟」，保持開啟，再撳「加入」。</li><li>從主畫面打開「記賬・本機」，再開始設定同記帳，毋須登入。</li></ol><p class="small muted">先加入主畫面，再開始輸入，避免 Safari 同主畫面 App 使用不同儲存空間。首次載入需要網絡；離線快取就緒後可以離線記帳。</p><h3>第一次設定</h3><p>去「設定」填銀行、MPay、現金同未還卡數，再去「預算」設定各分類金額。固定開支、找卡數日期同投資目標由你自己設定。</p><h3>月底備份</h3><p>CSV 用嚟睇帳同分析；換機或完整還原要用 JSON 完整備份。下載後確認已存入「檔案」→「我的 iPhone」，唔需要用 iCloud。</p><p class="small muted">資料只喺呢個瀏覽器／主畫面 App。唔好用私密瀏覽；清除網站資料、移除 App 或換機前先匯出完整備份。只留喺同一部手機嘅備份，手機遺失時亦會一齊失去。</p><button class="btn wide" onclick="document.querySelector('#modal').close()">明白</button>`)}
function bind(){const all=(s,fn)=>$('#app').querySelectorAll(s).forEach(b=>b.onclick=()=>fn(b));upgradeBind(all);all('[data-new-recurring]',()=>recurringForm());all('[data-recurring]',b=>recurringForm(b.dataset.recurring));all('[data-card-done]',toggleCardReminder);all('[data-pending-recurring]',()=>{reviewOnly=true;categoryFilter='';search='';filter='';location.hash='ledger';render()});all('[data-import]',()=>$('#import-file').click());all('[data-add-holding]',()=>holdingForm());all('[data-plan-settings]',investmentPlanForm);all('[data-edit-holding]',b=>holdingForm(b.dataset.editHolding));all('[data-invest-rate]',investmentRateForm);all('[data-snapshot]',saveSnapshotForm);all('[data-copy-budget]',copyBudgetForm);all('[data-budget-reference]',budgetReference);all('[data-accounts]',accountsForm);all('[data-new-category]',b=>cat(b.dataset.newCategory)?.type.includes('支出')?quickExpense(b.dataset.newCategory):transactionForm(null,b.dataset.newCategory));all('[data-budget]',b=>budgetForm(b.dataset.budget));all('[data-new-cat]',newCategory);all('[data-edit-category]',b=>categoryForm(b.dataset.editCategory));all('[data-restore-category]',b=>{commit(restoreCategory(state,b.dataset.restoreCategory));toast('分類已還原。')});all('[data-new-goal]',()=>goalForm());all('[data-edit-goal]',b=>goalForm(b.dataset.editGoal));all('[data-reserve]',b=>reserveForm(b.dataset.reserve));all('[data-edit-tx]',b=>transactionForm(b.dataset.editTx));all('[data-transfer]',()=>transactionForm(null,null,'transfer'));all('[data-repay]',()=>transactionForm(null,null,'repay'));all('[data-backup]',backup);all('[data-csv]',csvExport);all('[data-help]',help);all('[data-category-ledger]',b=>{categoryFilter=b.dataset.categoryLedger;search='';filter='';reviewOnly=false;location.hash='ledger';render()});all('[data-month]',b=>{month=b.dataset.month;reviewOnly=false;render()});if(view==='ledger'){ledgerRows();$('#search').oninput=e=>{search=e.target.value;ledgerRows()};$('#type-filter').onchange=e=>{filter=e.target.value;ledgerRows()};$('#review-filter').onclick=()=>{reviewOnly=!reviewOnly;render()};if($('#clear-category'))$('#clear-category').onclick=()=>{categoryFilter='';render()}}if($('#default-payment'))$('#default-payment').onchange=e=>{const n=structuredClone(state);n.settings.defaultPayment=e.target.value;try{commit(n);toast('預設付款方式已更新。')}catch(err){toast(err.message)}};if($('#raw-backup'))$('#raw-backup').onclick=()=>download('記賬-原始救援資料.txt',localStorage.getItem(KEY)||'','text/plain');}
$('#month').onchange=e=>{if(/^\d{4}-(0[1-9]|1[0-2])$/.test(e.target.value)){month=e.target.value;render()}};$('#add').onclick=()=>quickExpense();$('#help').onclick=help;window.addEventListener('focus',refreshRecurring);document.addEventListener('visibilitychange',()=>{if(!document.hidden)refreshRecurring()});window.addEventListener('hashchange',()=>{refreshRecurring();render();window.scrollTo(0,0)});render();
if('serviceWorker' in navigator){let hadController=!!navigator.serviceWorker.controller;navigator.serviceWorker.addEventListener('controllerchange',()=>{if(hadController)toast('新版本已就緒；完成目前操作後重新開啟。');hadController=true});navigator.serviceWorker.register('./sw.js').then(()=>navigator.serviceWorker.ready).catch(()=>toast('離線模式未能啟用，暫時請保持網絡連線。'));}
if(navigator.storage?.persist)navigator.storage.persist().catch(()=>{});
