if(document.modelContext?.registerTool){for(const tool of [{name:'read_budget_summary',title:'睇預算概況',description:'Read the selected month budget summary and current available balance from this device only.',inputSchema:{type:'object',properties:{month:{type:'string',pattern:'^\\d{4}-(0[1-9]|1[0-2])$'}},required:['month'],additionalProperties:false},annotations:{readOnlyHint:true},execute:({month:m})=>{if(!/^\d{4}-(0[1-9]|1[0-2])$/.test(m))throw Error('Invalid month');const v=stats(state,m),a=available(state);return {currency:'MOP',month:m,income:v.income/100,expenses:v.expense/100,budgetRemaining:v.wantLeft/100,available:a.ready?a.value/100:null}}},{name:'start_expense_entry',title:'開始記帳',description:'Open the visible expense form without saving any transaction. User reviews and saves it.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:false},execute:(args)=>{if(!args||Object.keys(args).length)throw Error('No parameters accepted');transactionForm();return {status:'form_opened',saved:false}}}]){try{Promise.resolve(document.modelContext.registerTool(tool)).catch(()=>{})}catch{}}}
function investmentCurrency(n){return new Intl.NumberFormat('en-US',{minimumFractionDigits:2,maximumFractionDigits:2}).format(n)}
function precise(n){return new Intl.NumberFormat('en-US',{maximumFractionDigits:8}).format(n)}
function investments(){const p=normalisePortfolio(state.portfolio),v=portfolioTotals(p),target=p.holdings.reduce((n,h)=>n+(h.target||0),0),snapshots=[...p.snapshots].sort((a,b)=>a.month.localeCompare(b.month));return pageHead('INVESTMENTS · MONTHLY REVIEW','月結投資檢視','<button class="btn primary" data-add-holding>＋ 持倉</button>')+investmentClosePanel()+`<div id="price-review">${priceReview()}</div>${investmentAnalysis()}<div class="layout"><section class="hero"><div class="hero-top"><span>投資資產總值</span><span class="pill">唔計入可用金額</span></div><div class="amount"><span class="currency">MOP</span>${money(v.valueMOP)}</div><p class="helper">USD ${investmentCurrency(v.valueUSD)} · 按你記錄嘅持有數量同價格計算，非即時報價。</p><div class="hero-footer"><div><small>持倉未實現損益 · USD</small><strong class="${v.pnlUSD!==null&&v.pnlUSD<0?'negative':'positive'}">${v.pnlUSD===null?'成本未填齊':(v.pnlUSD>=0?'+':'')+investmentCurrency(v.pnlUSD)}</strong></div><div><small>未實現回報率</small><strong>${v.pnlPct===null?'—':v.pnlPct.toFixed(2)+'%'}</strong></div></div><p class="micro" style="margin-top:15px">用同一 USD 成本同市值計算；唔包括已實現損益、股息、交易費用及歷史換匯損益。</p></section><section class="panel"><div class="section-title"><h3>資產分佈</h3><button class="link" data-invest-rate>匯率設定</button></div><div class="split-bar" aria-label="資產類別佔比">${Object.entries(v.groups).map(([g,n],i)=>`<i style="width:${pct(n,v.valueUSD)}%;background:${colours[i%6]}"></i>`).join('')}</div>${Object.entries(v.groups).map(([g,n],i)=>`<div class="row small" style="margin-top:14px"><span><i class="dot" style="background:${colours[i%6]}"></i>${esc(g)}</span><span>${v.valueUSD?(n/v.valueUSD*100).toFixed(1):'0.0'}%</span></div>`).join('')||'<p class="small muted" style="margin-top:15px">新增持倉後就會顯示分佈。</p>'}<div class="rule"></div><p class="small muted">換算：1 USD = ${precise(p.rate)} MOP</p><p class="micro">${state.portfolio?'原始匯出參考：'+esc(p.asOf||'未設定'):'未有投資資料'}。每隻資產嘅價格日期列喺持倉卡片。</p>${target&&Math.abs(target-1)>.00001?`<p class="small negative">原有目標配置合計 ${(target*100).toFixed(0)}%，未滿 100%；暫時唔作買賣建議。</p>`:''}</section></div><div class="section-title" style="margin-top:28px"><h2>持倉 · ${p.holdings.length} 項</h2><small>撳持倉修改數量／價格</small></div><div class="holding-grid">${p.holdings.map(h=>{const value=h.quantity*h.price,pnl=h.averageCost===null?null:(h.price-h.averageCost)*h.quantity;return `<button class="holding-card" data-edit-holding="${esc(h.id)}"><div class="row"><div><strong>${esc(h.symbol)}</strong><span class="tag">${esc(h.group)}</span></div><span class="muted">修改 ↗</span></div><p class="small muted">${esc(h.name)}</p><div class="row"><span class="stat">${investmentCurrency(value)}</span><span class="micro">USD 市值</span></div><div class="holding-values"><div><span>持有數量</span><strong>${precise(h.quantity)}</strong></div><div><span>記錄價格 · USD</span><strong>${precise(h.price)}</strong></div><div><span>平均成本 · USD</span><strong>${h.averageCost===null?'未填':precise(h.averageCost)}</strong></div><div><span>未實現損益 · USD</span><strong class="${pnl!==null&&pnl<0?'negative':'positive'}">${pnl===null?'—':investmentCurrency(pnl)}</strong></div></div><p class="micro">價格日期 ${esc(h.priceAsOf)}${h.target!==null?' · 目標配置 '+(h.target*100).toFixed(1)+'%':''}</p></button>`}).join('')||'<div class="panel empty full"><h3>由你嘅股票、ETF 同 Crypto 開始。</h3><p>手動加入第一隻資產，再設定你嘅投資目標。</p></div>'}</div><div class="layout" style="margin-top:24px"><section class="panel"><div class="section-title"><h3>每月資產快照</h3><button class="link" data-snapshot>儲存快照</button></div><p class="micro">資產值變化包括入金、出金同市場升跌，唔等於投資回報。</p>${snapshots.map(s=>`<div class="snapshot-row"><span class="small">${esc(s.month)}</span><div><div class="progress"><i style="width:${pct(s.valueMOP,Math.max(...snapshots.map(x=>x.valueMOP)))}%;background:var(--gold)"></i></div></div><span class="small">${money(s.valueMOP)}</span></div>`).join('')||'<p class="small muted">月底更新持倉同價格，再儲存快照。</p>'}</section><section class="panel"><h3>最近持倉更新</h3><p class="micro" style="margin-top:12px">只記持倉調整，唔會再次扣銀行餘額。真正轉出投資資金，請用日常「記一筆」。</p>${p.changes.slice(0,6).map(c=>`<div class="transaction"><div><p class="small">${esc(c.symbol)} · ${esc(c.action)}</p><p class="micro">${esc(c.date)} · 數量 ${precise(c.quantity)} · 價格 USD ${precise(c.price)}</p></div></div>`).join('')||'<p class="small muted">更新持倉後會留低記錄。</p>'}</section></div><section class="panel" style="margin-top:24px"><details><summary>原表投資入金紀錄 · ${p.funding.length} 筆</summary><p class="small muted">獨立保留作參考，唔會合併到日常流水，避免重複扣款。呢個係入金成本，唔等於目前持倉成本。</p><div class="table-wrap"><table><thead><tr><th>日期</th><th>平台</th><th>付出 MOP</th><th>收到</th></tr></thead><tbody>${[...p.funding].sort((a,b)=>b.date.localeCompare(a.date)).map(f=>`<tr><td>${esc(f.date)}</td><td>${esc(f.platform)}</td><td>${money(f.amountMOP)}</td><td>${precise(f.received)} ${esc(f.currency)}</td></tr>`).join('')}</tbody></table></div></details></section>`}
function investmentNumber(value,label,allowNull=false){if(allowNull&&String(value).trim()==='')return null;if(!/^\d+(\.\d{1,8})?$/.test(String(value).trim()))throw Error(label+'請輸入非負數，最多八個小數位。');const n=Number(value);if(!Number.isFinite(n)||n>1e12)throw Error(label+'超出範圍。');return n}
function holdingForm(id=null){const p=normalisePortfolio(state.portfolio),h=p.holdings.find(h=>h.id===id);modal(h?'更新 '+h.symbol:'新增投資持倉',`<p class="small muted">持倉以 USD 計價。買賣後更新數量同平均成本；查看資產值時更新價格。唔會改日常帳戶餘額。</p><form><div class="form-grid">${field('代號',input('symbol',h?.symbol||'','text','required maxlength="30" placeholder="例如 VT"'))}${field('資產類別',`<select name="group">${['股票/ETF','Crypto','Gold','Cash','其他'].map(g=>opt(g,g,h?.group||'股票/ETF')).join('')}</select>`)}${field('名稱',input('name',h?.name||'','text','required maxlength="100"'),true)}${field('持有數量',input('quantity',h?String(Number(h.quantity.toFixed(8))):'','text','required inputmode="decimal"'))}${field('平均成本 · USD（可留空）',input('averageCost',h?.averageCost===null||!h?'':String(Number(h.averageCost.toFixed(8))),'text','inputmode="decimal"'))}${field('價格 · USD',input('price',h?String(Number(h.price.toFixed(8))):'','text','required inputmode="decimal"'))}${field('價格日期',input('priceDate',h?.priceAsOf||today(),'text','required placeholder="YYYY-MM 或 YYYY-MM-DD"'))}${field('目標配置 %（可留空）',input('target',h?.target===null||!h?'':String(Number((h.target*100).toFixed(6))),'text','inputmode="decimal"'))}${field('備註',input('note',h?.note||'','text','maxlength="1000"'))}</div>${h?.priceAsOf.length===7?'<p class="micro">原表價格只標示月份。請核對價格日期，唔好將舊價當今日報價。</p>':''}${actions('儲存持倉')}${h?'<button type="button" class="link negative" id="remove-holding">移除呢項持倉</button>':''}</form>`,f=>{const priceDate=String(f.get('priceDate')).trim();if(!/^\d{4}-(0[1-9]|1[0-2])(?:-(0[1-9]|[12]\d|3[01]))?$/.test(priceDate)||(priceDate.length===10&&new Date(priceDate+'T12:00:00Z').toISOString().slice(0,10)!==priceDate))throw Error('價格日期請填 YYYY-MM 或 YYYY-MM-DD。');if(priceDate>today())throw Error('價格日期唔可以係將來。');const target=investmentNumber(f.get('target'),'目標配置',true);if(target!==null&&target>100)throw Error('目標配置唔可以超過 100%。');const item={id:h?.id||uid(),symbol:String(f.get('symbol')).trim().toUpperCase(),name:String(f.get('name')).trim(),group:f.get('group'),quantity:investmentNumber(f.get('quantity'),'數量'),averageCost:investmentNumber(f.get('averageCost'),'平均成本',true),price:investmentNumber(f.get('price'),'價格'),priceAsOf:priceDate,target:target===null?null:target/100,note:String(f.get('note')).trim()};if(!item.name||!item.symbol)throw Error('請填代號同名稱。');const n=structuredClone(state);n.portfolio=updateHolding(p,item,today());validatePortfolio(n.portfolio);commit(n);$('#modal').close();toast('持倉已儲存，日常餘額保持不變。')});if(h)$('#remove-holding').onclick=()=>modal('移除 '+h.symbol+'？',`<p class="small muted">唔會產生賣出收入或改銀行餘額；已保存嘅月度快照會保留。只係清倉嘅話，可以改數量為 0。</p><form>${actions('確認移除')}</form>`,()=>{const n=structuredClone(state),p=normalisePortfolio(n.portfolio);p.holdings=p.holdings.filter(x=>x.id!==id);p.changes.unshift({date:today(),symbol:h.symbol,action:'移除持倉',quantity:h.quantity,price:h.price});p.valueMOP=portfolioTotals(p).valueMOP;n.portfolio=p;commit(n);$('#modal').close();toast('持倉已移除。')})}
function investmentRateForm(){const p=normalisePortfolio(state.portfolio);modal('投資換算匯率',`<p class="small muted">只影響投資總值嘅 MOP 顯示，唔會更改銀行、預算或原有入金紀錄。請按你採用嘅估值匯率更新。</p><form>${field('1 USD = 幾多 MOP',input('rate',p.rate,'text','required inputmode="decimal"'))}${actions()}</form>`,f=>{const rate=investmentNumber(f.get('rate'),'匯率');if(rate<=0||rate>10000)throw Error('請填有效正數匯率。');const n=structuredClone(state);p.rate=rate;p.valueMOP=portfolioTotals(p).valueMOP;n.portfolio=p;commit(n);$('#modal').close();toast('投資換算匯率已更新。')})}
function saveSnapshotForm(){const p=normalisePortfolio(state.portfolio);if(!p.holdings.length){toast('先匯入或新增持倉。');return}modal('儲存月度資產快照',`<p class="small muted">會保存而家嘅持倉同估值 ${moneyText(portfolioTotals(p).valueMOP)}。請先用上面嘅收市價工具更新，再核對所選月份嘅持有數量。快照係估值記錄，唔等於投資回報。</p><form>${field('快照月份',input('snapshotMonth',month,'month','required'))}<label class="check" style="margin-top:16px"><input type="checkbox" name="replace"><span>如果呢個月已有快照，我確認取代。</span></label>${actions('儲存快照')}</form>`,f=>{const m=f.get('snapshotMonth');if(m>today().slice(0,7))throw Error('唔可以儲存未來月份。');if(p.holdings.some(h=>h.quantity>0&&!h.priceAsOf.startsWith(m)))throw Error('部分價格唔屬於快照月份，請先更新或手動核對日期。');if(p.snapshots.some(s=>s.month===m)&&!f.get('replace'))throw Error('呢個月已有快照，請先確認取代。');const n=structuredClone(state);p.snapshots=p.snapshots.filter(s=>s.month!==m);p.snapshots.push({id:uid(),month:m,valueMOP:portfolioTotals(p).valueMOP,source:(m>=today().slice(0,7)||p.holdings.some(h=>h.priceStatus==='provisional'))?'手動儲存（暫錄）':'手動儲存',holdings:structuredClone(p.holdings),rate:p.rate});n.portfolio=p;commit(n);$('#modal').close();toast('呢個月嘅資產快照已儲存。')})}
function priorMonths(m,count=3){const [y,mo]=m.split('-').map(Number);return Array.from({length:count},(_,i)=>{const d=new Date(Date.UTC(y,mo-2-i,1));return d.toISOString().slice(0,7)}).reverse()}
function observations(c){return priorMonths(month).map(m=>{const entries=state.transactions.filter(t=>t.date.startsWith(m));if(entries.length){const selected=entries.filter(t=>t.categoryId===c.id&&t.kind==='expense');return {month:m,value:selected.length?selected.reduce((n,t)=>n+t.amount,0):null,source:'流水帳'}}const h=(state.budgetHistory||[]).find(h=>h.month===m);return {month:m,value:h?.actuals[c.name]??null,source:h?.source||'未有資料'}})}
function budgetGuide(){const incomeCat=state.categories.find(c=>c.name==='薪資'),income=incomeCat?budget(state,incomeCat,month):0,expenses=state.categories.filter(c=>c.type.includes('支出')).reduce((n,c)=>n+budget(state,c,month),0),saving=state.categories.filter(c=>c.type==='投資/儲蓄').reduce((n,c)=>n+budget(state,c,month),0),left=income-expenses-saving;return `<section class="panel" style="margin:20px 0"><div class="section-title"><h2>預算點先算合適？</h2><button class="link" data-budget-reference>睇歷史參考 ↗</button></div><div class="grid-3"><div class="metric"><span class="micro">每月薪資計劃</span><strong>${money(income)}</strong></div><div class="metric"><span class="micro">生活 ＋ 投資／儲蓄</span><strong>${money(expenses+saving)}</strong></div><div class="metric"><span class="micro">計劃剩餘緩衝</span><strong class="${left<0?'negative':'positive'}">${money(left)}</strong></div></div><p class="small muted" style="margin-top:16px">月頭定計劃；平時只記支出，餘額會自己扣。月尾睇差額，再決定下月改唔改。</p><p class="small ${left<0?'negative':'muted'}">${income===0?'先喺薪資分類填每月穩定收入。唔好將一次性花紅當每月收入。':left<0?'目前預算超過薪資，要降低部分支出／儲蓄計劃，或者清楚指定由已有資金支付。':'剩餘緩衝唔代表全部可以額外使；未計漏記支出同額外目標留起。'}</p><details><summary>幾時應該改預算？</summary><ul class="small muted"><li>租金、電話月費變咗：按新賬單更新。</li><li>每月反覆超支：先查漏記／重複記，再決定減開支定調高預算。</li><li>旅行、手機、年度保費：用目標提前留起，唔好全當日常消費。</li><li>唔好為咗令超支提示消失而事後加預算。</li></ul></details><p class="micro">舊有「信用卡」主分類可能係還款，先核對有冇重複計；原表 MOP 1 嘅欄位亦可能只係佔位。</p><div class="row wrap"><button class="btn" data-copy-budget>沿用上月預算</button><button class="link" data-supplement>加入舊表歷史參考</button></div></section>`}
function budgetReference(){const months=priorMonths(month);modal('用歷史幫手，唔係照抄歷史',`<p class="small muted">參考 ${months.join('、')} 三個已過月份。中位數只供比較，唔會自動改你嘅預算。「—」係未有記錄，唔當 0；先核對完整性同一次性開支。</p><div class="table-wrap"><table><thead><tr><th>分類</th>${months.map(m=>`<th>${m}</th>`).join('')}<th>中位數</th><th>目前預算</th></tr></thead><tbody>${state.categories.filter(c=>c.type.includes('支出')).map(c=>{const obs=observations(c),nums=obs.map(o=>o.value).filter(v=>v!==null).sort((a,b)=>a-b),median=nums.length?(nums[Math.floor((nums.length-1)/2)]+nums[Math.ceil((nums.length-1)/2)])/2:null;return `<tr><td>${esc(c.name)}</td>${obs.map(o=>`<td>${o.value===null?'—':money(o.value)}</td>`).join('')}<td>${median===null?'—':money(median)}</td><td>${money(budget(state,c,month))}</td></tr>`}).join('')}</tbody></table></div><p class="micro" style="margin-top:14px">有日常流水嘅月份優先用流水；否則用匯入嘅月度表。來源分類口徑有變，尤其信用卡及車輛交通，唔應直接比較「必要／想要」總額。</p>${(state.budgetHistory||[]).filter(h=>months.includes(h.month)&&h.note).map(h=>`<p class="small muted">${esc(h.month)} 原表大額備註：${esc(h.note)}</p>`).join('')}<button class="btn wide" onclick="document.querySelector('#modal').close()">明白，我會核對再決定</button>`)}
function copyBudgetForm(){const previous=priorMonths(month,1)[0];modal('沿用 '+previous+' 嘅預算？',`<p class="small muted">將上月每個分類嘅預算複製去 ${esc(month)}，會取代 ${esc(month)} 已設定嘅金額。其他月份同交易唔會改。</p><form>${actions('複製到 '+month)}</form>`,()=>{const n=structuredClone(state);n.budgetOverrides[month]=Object.fromEntries(state.categories.map(c=>[c.id,budget(state,c,previous)]));commit(n);$('#modal').close();toast('已沿用上月預算，可以再按需要調整。')})}

function changeLabel(a,b){const d=spendingChange(a,b);if(!d)return '資料未齊，暫未比較';if(d.amount===0)return '同上月一樣';return `${d.amount>0?'多使':'少使'} MOP ${money(Math.abs(d.amount))}${d.percent===null?'（上月為 0，唔計百分比）':` · ${Math.abs(d.percent).toFixed(1)}%`}`}
function categoryComparison(c){const prev=monthSpending(state,priorMonths(month,1)[0]),curr=monthSpending(state,month);const a=curr.byCategory[c.id]??null,b=prev.byCategory[c.id]??null;return `<div class="category-comparison"><span>上月已記錄 ${b===null?'—':'MOP '+money(b)}</span><strong>${changeLabel(a,b)}</strong></div>`}
function spendingComparison(){const previous=priorMonths(month,1)[0],a=monthSpending(state,month),b=monthSpending(state,previous),max=Math.max(a.total||0,b.total||0,1),isCurrent=month===today().slice(0,7);return `<section class="panel spending-comparison"><div class="section-title"><h2>同上個月使咗幾多？</h2><span class="tag">支出比較</span></div><p class="small muted">${isCurrent?'今月截至今日，對比上月全月':'所選月份，對比上一個月'} · MOP</p><div class="comparison-bars">${[[month,a,'current'],[previous,b,'previous']].map(([m,v,k])=>`<div class="comparison-line ${k}"><div class="row"><span>${m}${k==='current'?' · 所選月份':' · 上個月'}</span><strong>${v.total===null?'未有資料':money(v.total)}</strong></div><div class="comparison-track"><i style="width:${pct(v.total||0,max)}%"></i></div><span class="micro">${v.source}${v.partial?' · 已知分類小計':''}</span></div>`).join('')}</div><p class="comparison-result">${changeLabel(a.total,b.total)}</p><p class="micro">流水只計消費，唔包括投資、轉帳同還卡數；舊表按已知支出分類加總。${isCurrent?'今月未完，少使唔代表全月會慳到。':''}包括標示為預填嘅待核對支出。未有資料唔當 0；舊表可能有缺項或信用卡重複記錄，請先核對。</p></section>`}

function priceReview(){const p=normalisePortfolio(state.portfolio);return `<section class="panel price-panel"><div class="section-title"><div><p class="eyebrow">${esc(month)} · 月結價格</p><h2>核對月底收市價</h2></div><button class="btn" data-snapshot>儲存月度快照</button></div><p class="small muted">本機版唔會自動查價。請對照券商所選月份最後交易日嘅收市價，再修改價格、日期、持有數量同平均成本。</p><div class="quote-list">${p.holdings.map(h=>`<div class="quote-row"><div><strong>${esc(h.symbol)}</strong><span class="micro">${esc(h.priceAsOf)} · 已記錄價格</span></div><strong>USD ${investmentCurrency(h.price)}</strong><button class="btn" data-edit-holding="${esc(h.id)}">更新價格</button></div>`).join('')||'<p class="muted">撳「＋ 持倉」，加入自己嘅股票或 ETF。</p>'}</div><p class="micro">月份未完嘅價格只係暫錄，唔代表月底收市價。資料唔會自動跟市場更新。</p></section>`}




function investmentAnalysis(){const p=normalisePortfolio(state.portfolio),plan=state.settings.investmentPlan||{contribution:0,years:null,drawdown:null,reserveReady:'unknown'},a=allocationAnalysis(p,month,plan.contribution),next=nextMonth(month),av=safety(state,today()),profileReady=plan.years!==null&&plan.drawdown!==null&&plan.reserveReady==='yes',issues=[];if(!av.ready||!av.planReady)issues.push('先核對戶口餘額同近期必要開支，投入試算先有足夠現金依據。');if(!a.validTargets)issues.push('目標配置合計 '+(a.targetTotal*100).toFixed(1)+'%，請先補齊至 100%。唔會擅自放大原有比例。');if(!profileReady)issues.push('先填投資年期、可接受跌幅同應急錢狀況；下面只係配置分析／試算。');if(a.stale.length)issues.push(a.stale.length+' 項持倉未有 '+month+' 嘅有效價格，先更新再做月結。');if(plan.drawdown!==null&&plan.drawdown<=10&&(a.groups.Crypto||0)+(a.groups['股票/ETF']||0)>0)issues.push('你只接受 '+plan.drawdown+'% 短期跌幅；股票同 Crypto 可以跌更多，先重新檢視目標配置，唔好直接照試算加碼。');if((a.groups.Crypto||0)>0)issues.push('目前 Crypto 佔 '+((a.groups.Crypto||0)*100).toFixed(1)+'%，價格可以大幅波動；唔應當作生活應急錢。');if(plan.years!==null&&plan.years<=3)issues.push('呢筆錢 3 年內會用：先分開近期用途資金，再考慮股票同 Crypto 配置。');if(plan.reserveReady==='no')issues.push('應急錢未準備好：下月先處理生活緩衝，再決定投入金額。');if(av.ready&&plan.contribution>Math.max(0,av.value))issues.push('試算投入金額高過目前可用現金；唔好直接照表買入。');const unfinished=month>=today().slice(0,7)||p.holdings.some(h=>h.quantity>0&&h.priceStatus==='provisional');if(unfinished)issues.push('所選月份未結束或包含暫錄價，下月方案仲係預覽。');const rows=[...a.rows].sort((x,y)=>(y.gap??-2)-(x.gap??-2));return `<section class="panel analysis-panel"><div class="section-title"><div><p class="eyebrow">${esc(next)} · 下月準備</p><h2>下一筆錢，點樣分配？</h2></div><button class="btn" data-plan-settings>設定投入／目標</button></div><div class="grid-3"><div class="metric"><span class="micro">計劃投入 · MOP</span><strong>${plan.contribution?money(plan.contribution):'未設定'}</strong></div><div class="metric"><span class="micro">股票／ETF 佔比</span><strong>${((a.groups['股票/ETF']||0)*100).toFixed(1)}%</strong></div><div class="metric"><span class="micro">Crypto 佔比</span><strong>${((a.groups.Crypto||0)*100).toFixed(1)}%</strong></div></div>${issues.length?`<div class="notice info" style="margin-top:18px"><ul class="analysis-notes">${issues.map(s=>`<li>${esc(s)}</li>`).join('')}</ul></div>`:''}<h3 style="margin-top:20px">目前配置 vs 你嘅目標</h3><p class="small muted">按目前記錄持倉計，唔係自動重建歷史持倉。差距用百分點表示。</p><div class="allocation-list">${rows.map(h=>`<div class="allocation-row"><div class="row"><strong>${esc(h.symbol)}</strong><span>${(h.weight*100).toFixed(1)}% → 目標 ${h.target===null?'未設定':(h.target*100).toFixed(1)+'%'}</span></div><div class="allocation-track"><i style="width:${pct(h.weight,1)}%"></i>${h.target!==null?`<b style="left:${pct(h.target,1)}%" title="目標 ${(h.target*100).toFixed(1)}%"></b>`:''}</div><p class="micro">${h.gap===null?'先設定目標':Math.abs(h.gap)<.0005?'接近目標':h.gap>0?'低過目標 '+(h.gap*100).toFixed(1)+' 個百分點':'高過目標 '+(-h.gap*100).toFixed(1)+' 個百分點'}${a.canSimulate?` · 新資金試算 MOP ${money(h.addMOP)}`:''}</p></div>`).join('')||'<p class="muted">加入持倉後，就會見到配置分析。</p>'}</div><h3 style="margin-top:22px">下月行動清單</h3><ol class="small action-list"><li>核對月底價格、持有數量同平均成本，再儲存 ${esc(month)} 快照。</li><li>${!a.validTargets?'補齊目標比例至 100%，包括想保留嘅現金部分。':!plan.contribution?'設定下月可以投入嘅金額，先扣生活開支同應急錢。':'檢查新資金試算：按投入後嘅目標缺口分配，未有缺口嘅標的先唔加碼。'}</li><li>${!profileReady?'填好投資年期、跌幅承受能力同應急錢狀況，再決定是否執行。':`用 ${plan.years} 年用途同可接受 ${plan.drawdown}% 跌幅檢視配置；可接受跌幅唔係止蝕保障，實際虧損可以更大。`}</li></ol>${plan.drawdown!==null?`<p class="small muted">情境試算：假設整個組合跌 ${plan.drawdown}%，帳面約減少 MOP ${money(Math.round(a.total*p.rate*100*plan.drawdown/100))}。呢個唔係預測，亦唔係最大虧損。</p>`:''}${a.canSimulate?`<details><summary>睇新資金分配試算 · MOP ${money(plan.contribution)}</summary><p class="small muted">按投入後目標金額嘅正差距比例分配新錢，唔計賣出。只係你所設目標嘅數學試算，未判斷比例是否適合你。</p><div class="table-wrap"><table><thead><tr><th>標的</th><th>新增 MOP</th><th>約數量</th><th>投入後佔比</th></tr></thead><tbody>${rows.map(h=>`<tr><td>${esc(h.symbol)}</td><td>${money(h.addMOP)}</td><td>${h.units===null?'—':precise(h.units)}</td><td>${(h.afterWeight*100).toFixed(1)}%</td></tr>`).join('')}</tbody></table></div><p class="micro">以記錄價格同 1 USD = ${precise(p.rate)} MOP 試算，未計手續費、買賣差價、稅同碎股限制；唔會自動落單。</p></details>`:''}<details style="margin-top:12px"><summary>點解咁分析？</summary><p class="small muted">按原定目標檢查偏離，將新資金分配到不足部分，係再平衡其中一種做法。風險承受能力同用錢年期仍然要一齊考慮；持有多隻 ETF 唔代表底層股票冇重疊，Crypto 亦唔等同現金。</p><a class="link" href="https://www.investor.gov/introduction-investing/getting-started/asset-allocation" target="_blank" rel="noopener noreferrer">Investor.gov：資產配置與再平衡 ↗</a><br><a class="link" href="https://www.investor.gov/introduction-investing/general-resources/news-alerts/alerts-bulletins/investor-alerts/crypto-asset-securities" target="_blank" rel="noopener noreferrer">Investor.gov：Crypto 風險 ↗</a></details></section>`}
function investmentPlanForm(){const p=normalisePortfolio(state.portfolio),plan=state.settings.investmentPlan||{};modal('下月投入同目標配置',`<form><div class="form-grid">${field('每月計劃投入 · MOP',input('contribution',plan.contribution?plan.contribution/100:'','text','required inputmode="decimal" placeholder="填你實際可投入金額"'))}${field('幾多年後要用呢筆錢？',input('years',plan.years??'','number','min="0" max="100" step="0.5" placeholder="可稍後填"'))}${field('最多接受短期跌幅 %',input('drawdown',plan.drawdown??'','number','min="0" max="100" step="1" placeholder="例如 20，可稍後填"'))}${field('生活／應急錢已另外留起？',`<select name="reserveReady">${[['unknown','未確認'],['yes','已留起'],['no','未留起']].map(([v,n])=>opt(v,n,plan.reserveReady||'unknown')).join('')}</select>`)}</div><h3 style="margin-top:20px">各標的目標配置 %</h3><p class="small muted">合計要 100% 先提供分配試算；唔知點分可以先留空，唔會自動替你決定。</p><div class="form-grid">${p.holdings.map((h,i)=>field(esc(h.symbol),input('target-'+i,h.target===null?'':Number((h.target*100).toFixed(6)),'text','inputmode="decimal"'))).join('')}</div>${actions('儲存設定')}</form>`,f=>{const n=structuredClone(state);const plan={contribution:amount(f.get('contribution')),years:investmentNumber(f.get('years'),'年期',true),drawdown:investmentNumber(f.get('drawdown'),'跌幅',true),reserveReady:f.get('reserveReady')};validateInvestmentPlan(plan);n.settings.investmentPlan=plan;p.holdings.forEach((h,i)=>{const v=investmentNumber(f.get('target-'+i),'目標比例',true);if(v!==null&&v>100)throw Error('每項目標唔可以超過 100%。');h.target=v===null?null:v/100});n.portfolio=validatePortfolio(p);commit(n);$('#modal').close();toast('已儲存；目標合計 100% 後會顯示分配試算。')})}
function recurringPanel(){const rows=(state.recurring||[]).filter(r=>!cat(r.categoryId)?.removedFrom),pending=state.transactions.filter(t=>t.estimated&&t.date.startsWith(month));return `<section class="panel recurring-panel"><div class="section-title"><div><p class="eyebrow">每月少啲重複輸入</p><h2>分類同固定開支</h2></div><button class="btn" data-new-recurring>＋ 固定開支</button></div><p class="small muted">按自己需要新增固定開支；信用卡係付款方式。訂閱可以用同一分類，服務名稱寫喺備註。</p><div class="recurring-list">${rows.map(r=>`<button class="recurring-item" data-recurring="${esc(r.id)}"><span><strong>${esc(r.name)}</strong><small>${esc(cat(r.categoryId)?.name)} · ${esc(r.payment)}</small></span><span><strong>${r.amount===null?'待填金額':'MOP '+money(r.amount)}</strong><small>${!r.enabled?'未啟用':r.frequency==='yearly'?'每年 '+r.startMonth.slice(5)+' 月':'每月'}${r.enabled?' · '+r.day+' 號預填':''}</small></span></button>`).join('')}</div><p class="micro" style="margin-top:12px">啟用後，到預填日期首次打開 App 會帶入當月記錄，只計當月，唔會補建錯過嘅月份。預填先計入預算，唔會改帳戶餘額；核對後可修改金額／確認付款。刪除當月預填後唔會再自動補返。</p>${pending.length?`<div class="notice info"><strong>${esc(month)} 有 ${pending.length} 筆預填待核對</strong><div class="pending-chips">${pending.map(t=>`<button class="link" data-edit-tx="${esc(t.id)}">${esc(t.note)} · ${money(t.amount)} ↗</button>`).join('')}</div></div>`:''}<details><summary>舊分類同歷史記錄</summary><p class="small muted">手動移除嘅分類由本月起預算為 0，可隨時還原。歷史記錄會保留，唔會改帳戶餘額。</p>${state.categories.filter(c=>c.archivedFrom).map(c=>`<div class="row small"><span>${esc(c.name)} · ${c.removedFrom?'已移除':'已停用'}</span>${c.removedFrom?`<button class="link" data-restore-category="${esc(c.id)}">還原分類</button>`:''}<button class="link" data-category-ledger="${esc(c.id)}">睇舊記錄 ↗</button></div>`).join('')}</details></section>`}
function recurringForm(id=null){const r=state.recurring?.find(x=>x.id===id),cats=state.categories.filter(c=>c.type.includes('支出')&&categoryActive(c,today()));modal(r?'設定 '+r.name:'新增固定開支',`<p class="small muted">呢度修改之後嘅預填範本；已產生嘅當月記錄請另外修改。範本金額唔會自動改分類預算。外幣訂閱用預計扣賬嘅 MOP 金額，月底按實際扣賬調整。</p><form><div class="form-grid">${field('項目名稱',input('name',r?.name||'','text','required maxlength="100"'),true)}${field('分類',`<select name="category">${cats.map(c=>opt(c.id,c.name,r?.categoryId||cats[0]?.id)).join('')}</select>`)}${field('付款方式',`<select name="payment">${Object.keys(payments).map(v=>opt(v,v,r?.payment||state.settings.defaultPayment)).join('')}</select>`)}${field('預填金額 · MOP',input('amount',r?.amount==null?'':r.amount/100,'text','inputmode="decimal" placeholder="未知道可留空"'))}${field('收費週期',`<select name="frequency">${[['unknown','未確認'],['monthly','每月'],['yearly','每年']].map(([v,n])=>opt(v,n,r?.frequency||'monthly')).join('')}</select>`)}${field('開始月份',input('startMonth',r?.startMonth||followingMonth(today().slice(0,7)),'month','required'))}${field('預填日期（每月幾號）',input('day',r?.day||1,'number','min="1" max="31" required'))}${field('原幣收費（只作備註）',input('original',r?.original||'','text','maxlength="1000" placeholder="例如 USD 20／月"'),true)}${field('備註',input('note',r?.note||'','text','maxlength="1000"'),true)}</div><p class="micro" style="margin-top:12px">年繳只喺開始月份嘅同一個月份預填；當月冇 29–31 號會用月底。唔會自動兌換外幣。</p><label class="check"><input type="checkbox" name="enabled" ${r?.enabled?'checked':''}><span>啟用自動預填（需先填好金額同週期）</span></label>${actions('儲存範本')}</form>`,f=>{const name=String(f.get('name')).trim(),value=String(f.get('amount')).trim();if(!name)throw Error('請填名稱。');const template={id:r?.id||uid(),name,categoryId:f.get('category'),amount:value?amount(value):null,payment:f.get('payment'),frequency:f.get('frequency'),startMonth:f.get('startMonth'),day:Number(f.get('day')),enabled:!!f.get('enabled'),original:String(f.get('original')).trim(),note:String(f.get('note')).trim()};const n=structuredClone(state);n.recurring=(n.recurring||[]).filter(x=>x.id!==template.id);n.recurring.push(template);validateRecurring(n);commit(n);$('#modal').close();toast('範本已儲存，已產生嘅記錄保持不變。')})}
function expenseNotice(){const pending=state.transactions.filter(t=>t.estimated&&t.date.startsWith(month));return pending.length?`<div class="notice info"><strong>${pending.length} 筆固定開支已預填，等你核對。</strong><p>已計入預算，未改銀行餘額或卡數。</p><button class="link" data-pending-recurring>核對預填記錄 ↗</button></div>`:''}
function cardReminder(){const m=today().slice(0,7),cfg=state.settings.cardReminder||{enabled:false,day:10},done=(state.settings.cardReminderDone||[]).includes(m),lastDay=new Date(+m.slice(0,4),+m.slice(5),0).getDate(),due=m+'-'+String(Math.min(cfg.day,lastDay)).padStart(2,'0'),active=cfg.enabled&&!done&&today()>=due;return `<section class="panel card-reminder ${active?'due':''}"><div class="section-title"><h3>找卡數提醒</h3><button class="link" data-card-settings>設定日期</button></div><p class="small">${!cfg.enabled?'未啟用，按銀行到期日設定。':active?'今月待核對 · '+due:done?'今月已處理':'每月 '+cfg.day+' 號提醒'}</p><p class="micro">只喺打開 App 時顯示，唔會背景推送。以銀行月結單金額同到期日為準。</p><div class="row wrap"><button class="btn" data-repay>記信用卡還款</button>${cfg.enabled?`<button class="link" data-card-done>${done?'重新設為未處理':'已處理今月'}</button>`:''}</div></section>`}
function toggleCardReminder(){const m=today().slice(0,7),n=structuredClone(state),done=n.settings.cardReminderDone||[];n.settings.cardReminderDone=done.includes(m)?done.filter(x=>x!==m):[...done,m].slice(-1200);commit(n);toast('已更新本機還款提示。')}
function refreshRecurring(){if(storageBroken)return;try{const next=prepareExpenseState(state,today());if(JSON.stringify(next)!==JSON.stringify(state))commit(next)}catch(e){toast('未能自動預填：'+e.message)}}
function syncBadge(){return '<a class="sync-badge" href="#settings">本機儲存 · 手動備份</a>'}
function homeBudgetPockets(st){const rows=state.categories.filter(c=>c.type.includes('支出')&&(categoryActive(c,today())||(st.byCategory[c.id]||0)>0)).map(c=>({c,index:state.categories.indexOf(c),limit:budget(state,c,month),used:st.byCategory[c.id]||0})).sort((a,b)=>Math.max(0,b.used-b.limit)-Math.max(0,a.used-a.limit));const over=rows.filter(r=>r.used>r.limit).length;return `<section class="home-budget-pockets"><div class="section-title"><div><h2>我嘅預算袋</h2><p class="small muted">${esc(month)} · ${over?`${over} 個分類超支`:'暫時未有分類超支'}</p></div><a class="link" href="#budgets">改預算 ↗</a></div><div class="pockets">${rows.map(({c,index,limit,used})=>{const left=limit-used;return `<button class="pocket ${left<0?'pocket-over':''}" data-category-ledger="${esc(c.id)}" style="--pocket-color:${colours[index%colours.length]};--fill:${pct(used,limit)}%"><div class="pocket-head"><strong>${esc(c.name)}</strong><span class="pocket-status ${left<0?'negative':''}">${left<0?'超支':limit===0?'預算為 0':left===0?'用盡':'預算內'}</span></div><div class="remaining ${left<0?'negative':''}">${left<0?'超支 ':left===0?'剩餘 ':'仲剩 '}${money(Math.abs(left))}</div><div class="small">已用 ${money(used)} ／ 預算 ${money(limit)}</div>${progress(used,limit)}${c.archivedFrom?'<span class="micro">舊分類記錄</span>':''}</button>`}).join('')||'<p class="muted">新增支出分類後，就會顯示預算袋。</p>'}</div><p class="micro pocket-help">撳預算袋睇明細；超支分類排先。待核對預填亦計入已用金額。</p></section>`}
function home(){const st=stats(state,month),safe=safety(state,today()),expenseBudget=state.categories.filter(c=>c.type.includes('支出')).reduce((n,c)=>n+budget(state,c,month),0),pending=st.ts.filter(t=>t.estimated).length;return pageHead('每日記帳','今日，記低就得。',syncBadge())+(!state.transactions.length&&state.accounts.every(a=>a.balance===null)?'<section class="notice info"><strong>由你自己嘅帳本開始</strong><p>先設定戶口餘額同分類預算，再新增固定開支或持倉。</p><div class="row wrap"><a class="btn" href="#settings">設定帳本</a><a class="btn" href="#budgets">設定預算</a></div></section>':'')+`<button class="quick-entry" data-quick>＋ 記一筆<span>金額 · 分類 · 付款方式</span></button>${homeBudgetPockets(st)}<div class="daily-metrics"><section class="panel"><p class="small muted">${esc(month)} 預算剩餘</p><strong class="stat ${expenseBudget<st.expense?'negative':''}">${moneyText(expenseBudget-st.expense)}</strong><p class="micro">已記支出 ${money(st.expense)}${pending?' · 包括 '+pending+' 筆待核對預填':''}</p><a class="link" href="#budgets">睇分類預算 ↗</a></section><section class="panel"><p class="small muted">目前扣除安全線後可用</p><strong class="stat ${safe.value<0?'negative':''}">${safe.ready?moneyText(safe.value):'先核對帳戶餘額'}</strong><p class="micro">${safe.planReady?'已扣保費、卡數、目標及近期必要開支。':'暫算：未核對近期必要開支，唔代表全部可以使。'}</p><button class="link" data-cash-plan>核對安全線 ↗</button></section></div>${insuranceCard(true)}${pending?`<a class="notice info block" href="#review">${pending} 筆固定開支等你月尾核對 ↗</a>`:''}<section class="panel"><div class="section-title"><h2>最近記錄</h2><a class="link" href="#ledger">全部明細 ↗</a></div>${st.ts.slice().sort((a,b)=>b.date.localeCompare(a.date)).slice(0,5).map(transactionRow).join('')||'<p class="muted">呢個月未有記錄。</p>'}</section><div class="row wrap page-links"><a class="btn" href="#goals">儲錢目標</a><a class="btn" href="#review">月尾核對</a></div>`}
function review(){return pageHead('每月一次','月尾核對。')+`<div class="review-steps"><button class="btn" data-accounts>1 · 核對戶口同卡數</button><button class="btn" data-pending-recurring>2 · 核對預填／舊記錄</button><a class="btn" href="#investments">3 · 投資月結</a><a class="btn" href="#settings">4 · 匯出帳本備份</a></div>`+expenseNotice()+`<details class="panel fold" open><summary>今月同上月比較</summary>${spendingComparison()}</details><details class="panel fold"><summary>固定開支及找卡數</summary>${recurringPanel()+cardReminder()}</details><details class="panel fold"><summary>分類管理</summary>${categorySettings()}</details><details class="panel fold"><summary>預算參考及教學</summary>${budgetGuide()}</details><details class="panel fold"><summary>保費同生活安全線</summary>${insuranceCard()+cashSummary()}</details>`}
function categorySettings(){return `<div class="row wrap"><p class="muted small">分類改名、合併或移除，統一喺呢度處理。</p><button class="btn" data-new-cat>＋ 新增分類</button></div><div class="category-actions">${state.categories.filter(c=>categoryActive(c,today())).map(c=>`<button class="btn" data-edit-category="${esc(c.id)}">${esc(c.name)}</button>`).join('')}</div>`}
function settings(){return pageHead('設定與保護','帳本有備份，先安心。')+backupPanel()+`<details class="panel fold"><summary>帳戶餘額及預設付款方式</summary>${cashSummary()}<button class="btn" data-accounts>核對銀行、MPay、現金及卡數</button><label class="field">預設付款方式<select id="default-payment">${Object.keys(payments).map(v=>opt(v,v,state.settings.defaultPayment)).join('')}</select></label><div class="row wrap"><button class="link" data-transfer>帳戶轉帳／MPay 增值</button><button class="link" data-repay>還信用卡</button></div></details><details class="panel fold"><summary>保費設定</summary>${insuranceCard()}</details><details class="panel fold"><summary>分類及固定開支</summary>${categorySettings()+recurringPanel()+cardReminder()}</details><details class="panel fold"><summary>匯出及安裝說明</summary><div class="settings-list"><button class="btn" data-csv>匯出流水 CSV</button><button class="btn" data-help>加入 iPhone 主畫面</button>${storageBroken?'<button class="btn danger" id="raw-backup">匯出原始資料作救援</button>':''}</div></details><p class="small muted">未連接銀行或 MPay。請定期對照實際餘額；自動預填仍然需要核對。</p>`}
function timeLabel(v){if(!v)return '未有紀錄';const d=new Date(v);return Number.isNaN(d.getTime())?esc(v):esc(d.toLocaleString('zh-HK',{timeZone:'Asia/Macau',hour12:false}))}
function backupPanel(){return `<section class="panel"><div class="section-title"><h2>本機帳本與備份</h2>${syncBadge()}</div><p class="small muted">記錄只儲存喺呢部裝置，唔會上載帳目，亦唔需要登入。清除網站資料或換機前，先下載完整備份。</p><dl class="status-list"><dt>最後匯出完整備份</dt><dd>${timeLabel(localMeta.lastExport)}</dd><dt>最後匯出 CSV</dt><dd>${timeLabel(localMeta.lastCsvExport)}</dd></dl><div class="settings-list"><button class="btn primary" data-csv>匯出 CSV 報表 ↓</button><button class="btn" data-backup>匯出完整備份 JSON ↓</button><button class="btn" data-import>匯入／還原完整備份 ↑</button><button class="btn" data-local-versions>查看本機還原副本</button></div><p class="micro">CSV 用嚟查看同分析；JSON 保留所有設定、預算、流水、持倉同投資月結，先可以完整還原。匯出時間只代表已發起下載，請確認檔案已存入「我的 iPhone」。本機還原副本最多 10 份，清除網站資料會一併刪除。</p></section>`}
function cashSummary(){const a=safety(state,today());return `<dl class="status-list"><dt>銀行＋MPay＋現金</dt><dd>${a.ready?moneyText(a.assets):'未核對'}</dd><dt>未還卡數</dt><dd>${moneyText(a.debt)}</dd><dt>其他目標已留起</dt><dd>${moneyText(a.saved)}</dd><dt>下一期保費安全線</dt><dd>${moneyText(a.insurance)}</dd><dt>近期必要開支</dt><dd>${state.settings.cashPlan?moneyText(a.living):'未填'}</dd><dt>扣除後可用</dt><dd>${a.ready?moneyText(a.value):'未能計算'}</dd></dl><p class="small muted">${a.planReady?'近期開支已核對；付款後記得更新剩餘所需，避免重複扣減。':'近期必要開支未核對或已過出糧日，請更新。'}戶口最後核對：${esc(state.settings.balanceAsOf||'未有')}。</p><button class="link" data-cash-plan>更新近期必要開支</button>`}
function cashPlanForm(){const c=state.settings.cashPlan;modal('下次出糧前，要保留幾多？',`<p class="small muted">只填仲未支付、亦未包含喺卡數、保費或儲錢目標內嘅必要開支。付款後調低剩餘所需，避免重複扣數。</p><form><div class="form-grid">${field('下次出糧日',input('nextIncome',c?.nextIncome||'','date','required'))}${field('仲需要 · MOP',input('required',c?c.required/100:'','text','required inputmode="decimal"'))}</div>${actions('更新安全線')}</form>`,f=>{if(f.get('nextIncome')<today())throw Error('請填今日或之後嘅出糧日。');const n=structuredClone(state);n.settings.cashPlan={required:amount(f.get('required')),nextIncome:f.get('nextIncome'),checkedAt:today()};commit(n);$('#modal').close()})}
function insuranceCard(compact=false){const a=safety(state,today()),p=a.premium;if(!p)return `<section class="panel insurance"><div class="section-title"><h2>下一期保費</h2><button class="link" data-insurance-settings>設定保費安全線</button></div><p class="small muted">錢留喺原本戶口，只喺可用金額中扣起。</p></section>`;const label=!a.ready?'未核對戶口，未能判斷':!a.planReady?'先核對戶口同近期開支':a.shortfall?'目前缺口 '+moneyText(a.shortfall):'按已核對資料，安全線足夠';return `<section class="panel insurance"><div class="section-title"><h2>下一期保費</h2><span class="tag">${esc(p.cycle)}${p.overdue?' · 待處理':''}</span></div><strong class="stat">${moneyText(p.amount)}</strong><p class="small">${esc(p.label)}</p><p class="${a.shortfall?'negative':'muted'} small">${label}</p><p class="micro">已從可用金額扣起，毋須轉去另一個戶口。</p><div class="row wrap"><button class="btn" data-pay-insurance>記錄已交保費</button><button class="link" data-insurance-settings>修改設定</button></div>${compact?'':cashSummary()}</section>`}
function insuranceSettings(){const p=state.settings.insurance,cats=state.categories.filter(c=>c.type.includes('支出')&&categoryActive(c,today()));modal('保費安全線',`<p class="small muted">每年按月份循環，預留下一期全額；付款後自動換下一期。保費分類只喺付款月份有預算，唔再每月攤分。其他儲錢目標唔好重複預留同一筆保費。</p><form><div class="form-grid">${field('保費分類',`<select name="category">${cats.map(c=>opt(c.id,c.name,p?.categoryId||cats.find(x=>x.name==='保費')?.id)).join('')}</select>`)}${field('由邊個月份開始追蹤',input('start',p?.startMonth||today().slice(0,7),'month','required'))}</div>${[0,1,2].map(i=>{const r=p?.policies[i];return `<fieldset><legend>保費項目 ${i+1}</legend><div class="form-grid">${field('名稱 '+(i+1),input('name'+i,r?.name||'','text','maxlength="60"'))}${field('每年付款月份 '+(i+1),input('month'+i,r?.month||'','number','min="1" max="12"'))}${field('金額 MOP '+(i+1),input('amount'+i,r?r.amount/100:'','text','inputmode="decimal"'))}</div></fieldset>`}).join('')}<label class="check"><input name="enabled" type="checkbox" ${p?.enabled?'checked':''}>啟用保費安全線</label>${actions('儲存保費設定')}</form>`,f=>{const policies=[];for(let i=0;i<3;i++){const name=String(f.get('name'+i)).trim();if(name||f.get('amount'+i)||f.get('month'+i))policies.push({name,month:Number(f.get('month'+i)),amount:amount(f.get('amount'+i))})}const n=structuredClone(state);n.settings.insurance={enabled:!!f.get('enabled'),categoryId:f.get('category'),startMonth:f.get('start'),policies};if(n.settings.insurance.enabled)for(const r of n.recurring||[])if(r.categoryId===f.get('category'))r.enabled=false;commit(n);$('#modal').close();toast('已更新保費安全線；同類自動預填已暫停，避免重複。')})}
function payInsuranceForm(){const p=nextPremium(state,today());if(!p)return;modal('記錄已交 '+p.cycle+' 保費',`<p class="small muted">${esc(p.label)}。呢個操作只記帳，唔會代你付款。儲存後解除呢期安全線，自動顯示下一期；如已經有同一筆支出，請先核對避免重複。</p><form><div class="form-grid">${field('實際已付 · MOP',input('amount',p.amount/100,'text','required inputmode="decimal"'))}${field('付款日期',input('date',today(),'date','required'))}${field('付款方式',`<select name="payment">${Object.keys(payments).map(v=>opt(v,v,state.settings.defaultPayment)).join('')}</select>`)}</div><label class="check"><input type="checkbox" name="apply" ${available(state).ready?'checked':''}>更新目前帳戶餘額（補記核對前付款，請取消）</label>${actions('記支出並切換下一期')}</form>`,f=>{if(state.transactions.some(t=>t.insuranceCycle===p.cycle))throw Error('呢期已記錄。');const value=amount(f.get('amount'));if(!value||f.get('date')>today())throw Error('請填實際已付款金額同日期。');const payment=f.get('payment'),c=cat(state.settings.insurance.categoryId),t={id:uid(),date:f.get('date'),type:c.type,kind:'expense',categoryId:c.id,amount:value,payment,accountId:payments[payment],toAccountId:null,note:p.label+'（'+p.cycle+' 保費）',insuranceCycle:p.cycle,imported:false,review:false,estimated:false,effects:[]};commit(saveTransaction(state,t,!!f.get('apply')));$('#modal').close();toast('保費已記低，安全線已換到下一期。')})}
function quickExpense(categoryId){const cats=state.categories.filter(c=>c.type.includes('支出')&&categoryActive(c,today())),selected=cats.find(c=>c.id===categoryId)||cats.find(c=>c.id===state.settings.lastCategory)||cats.find(c=>c.name==='美食')||cats[0];if(!selected){transactionForm();return}modal('記一筆',`<form><div class="form-grid">${field('金額 · MOP',input('amount','','text','required inputmode="decimal" autofocus placeholder="0.00" class="amount-input"'),true)}${field('分類',`<select name="category">${cats.map(c=>opt(c.id,c.name,selected.id)).join('')}</select>`)}${field('付款方式',`<select name="payment">${Object.keys(payments).map(v=>opt(v,v,state.settings.quickPayment||state.settings.defaultPayment)).join('')}</select>`)}</div><details style="margin-top:12px"><summary>備註及日期（可選）</summary><div class="form-grid">${field('備註',input('note','','text','maxlength="3000" placeholder="例如：午餐、訂閱"'),true)}${field('日期',input('date',today(),'date','required'))}</div></details><p id="quick-preview" class="inline-preview"></p><label class="check"><input type="checkbox" name="apply" ${available(state).ready?'checked':''}>更新目前帳戶餘額</label>${!available(state).ready?'<p class="small muted">未核對帳戶，今次只記支出同預算。</p>':''}${actions('記下')}</form><button class="link" id="advanced-entry">收入、轉帳或信用卡還款 ↗</button>`,f=>{const c=cat(f.get('category')),value=amount(f.get('amount')),payment=f.get('payment'),d=f.get('date');if(!value||d>today())throw Error('請填有效金額同已發生日期。');const t={id:uid(),date:d,type:c.type,kind:'expense',categoryId:c.id,amount:value,payment,accountId:payments[payment],toAccountId:null,note:String(f.get('note')).trim(),imported:false,review:false,estimated:false,effects:[]};const n=saveTransaction(state,t,!!f.get('apply'));n.settings.lastCategory=c.id;n.settings.quickPayment=payment;commit(n);$('#modal').close();toast('已記低。')});const f=$('#modal-content form'),preview=()=>{let v=0;try{v=amount(f.elements.amount.value||'0')}catch{}const c=cat(f.elements.category.value),m=f.elements.date.value.slice(0,7),left=budget(state,c,m)-(stats(state,m).byCategory[c.id]||0)-v;$('#quick-preview').textContent=c.name+'：記低後'+(left<0?'超出 ':'尚餘 ')+moneyText(Math.abs(left))+(state.transactions.some(t=>t.estimated&&t.categoryId===c.id&&t.date.startsWith(m))?'。已有同類預填，請先核對避免重複。':'')};f.addEventListener('input',preview);preview();$('#advanced-entry').onclick=()=>transactionForm();}
function investmentClosePanel(){const r=(state.investmentCloses||[]).find(x=>x.month===month),p=r?monthInvestment(r):null,trades=(state.investmentTrades||[]).filter(t=>t.date.startsWith(month));return `<section class="panel fold"><div class="section-title"><div><p class="eyebrow">${esc(month)} · 對照券商月結單</p><h2>投資月結</h2></div><button class="btn" data-invest-close>${r?'修改月結':'填寫月結'}</button></div>${r?`<div class="grid-3"><div class="metric"><span>月底資產＋券商現金</span><strong>${moneyText(r.closing)}</strong></div><div class="metric"><span>淨投入</span><strong>${moneyText(p.netFunding)}</strong></div><div class="metric"><span>扣除資金進出後損益</span><strong class="${p.pnl<0?'negative':'positive'}">${moneyText(p.pnl)}</strong></div></div><dl class="status-list"><dt>股息（稅前）</dt><dd>${moneyText(r.dividends)}</dd><dt>費用</dt><dd>${moneyText(r.fees)}</dd><dt>稅項</dt><dd>${moneyText(r.taxes)}</dd><dt>券商已實現損益</dt><dd>${r.realised===null?'未填':moneyText(r.realised)}</dd></dl><p class="micro">損益＝月底總資產 − 月初總資產 − 入金 ＋ 提款。股息、費用及稅項已反映喺總資產，唔會再加減一次。${month>=today().slice(0,7)?'本月未完，數字只作暫錄。':''}</p>`:'<p class="muted small">持倉升跌未計資金進出。填月初／月底資產（包括券商現金）、入金同提款後，先會計月度損益。</p>'}<details><summary>買賣記錄 · ${trades.length} 筆</summary><button class="btn" data-new-trade>＋ 記買入／賣出</button>${trades.map(t=>{const pnl=tradeProfit(t);return `<button class="transaction" data-trade="${esc(t.id)}"><span class="transaction-body"><strong>${esc(t.symbol)} · ${t.side==='buy'?'買入':'賣出'}</strong><p class="micro">${esc(t.date)} · ${precise(t.quantity)} 股／單位 · ${esc(t.currency)} ${investmentCurrency(t.price)}</p><p class="micro">${pnl===null?'成本未齊或非賣出，未計已實現損益':'按填寫成本計損益：'+esc(t.currency)+' '+money(pnl)}</p></span></button>`}).join('')}<p class="micro">呢度係交易備忘錄，唔會再改持倉或銀行餘額。月底對照券商核對；已有持倉唔會由部分買賣記錄倒推成本。</p></details></section>`}
function investmentCloseForm(){const r=(state.investmentCloses||[]).find(x=>x.month===month);modal(month+' 投資月結',`<p class="small muted">全部填 MOP 換算金額，月初同月底都包括券商現金。入金／提款只計投資組合邊界以外嘅資金；組合內買賣、股息及戶口互轉唔當入金。</p><form><div class="form-grid">${[['opening','月初總資產'],['closing','月底總資產'],['deposits','本月入金'],['withdrawals','本月提款'],['dividends','股息（稅前）'],['fees','費用'],['taxes','稅項']].map(([k,label])=>field(label+' · MOP',input(k,r?r[k]/100:'','text','required inputmode="decimal"'))).join('')}${field('券商已實現損益 · MOP（可留空）',input('realised',r?.realised==null?'':r.realised/100,'text','inputmode="decimal" placeholder="虧損可填負數"'))}${field('備註',input('note',r?.note||'','text','maxlength="2000"'),true)}</div><p class="micro">只儲存月結資料，唔會改日常帳本餘額或重複計股息。</p>${actions('儲存月結')}</form>`,f=>{const n=structuredClone(state),row={month,note:String(f.get('note')).trim()};for(const k of ['opening','closing','deposits','withdrawals','dividends','fees','taxes'])row[k]=amount(f.get(k));const realised=String(f.get('realised')).trim();row.realised=realised===''?null:(realised.startsWith('-')?-amount(realised.slice(1)):amount(realised));n.investmentCloses=[...(n.investmentCloses||[]).filter(x=>x.month!==month),row];commit(n);$('#modal').close();toast('投資月結已儲存。')})}
function tradeForm(id=null){const old=(state.investmentTrades||[]).find(x=>x.id===id);modal(old?'修改買賣記錄':'記買入／賣出',`<form><div class="form-grid">${field('日期',input('date',old?.date||today(),'date','required'))}${field('買賣',`<select name="side">${opt('buy','買入',old?.side||'buy')}${opt('sell','賣出',old?.side||'buy')}</select>`)}${field('標的',input('symbol',old?.symbol||'','text','required maxlength="30"'))}${field('幣別',`<select name="currency">${['USD','HKD','MOP'].map(v=>opt(v,v,old?.currency||'USD')).join('')}</select>`)}${field('數量',input('quantity',old?.quantity||'','text','required inputmode="decimal"'))}${field('每股／單位成交價',input('price',old?.price??'','text','required inputmode="decimal"'))}${field('費用（同幣別）',input('fees',old?old.fees/100:'0','text','required inputmode="decimal"'))}${field('稅項（同幣別）',input('taxes',old?old.taxes/100:'0','text','required inputmode="decimal"'))}${field('今次賣出部分嘅總成本（同幣別，可留空）',input('costBasis',old?.costBasis==null?'':old.costBasis/100,'text','inputmode="decimal"'),true)}${field('備註',input('note',old?.note||'','text','maxlength="1000"'),true)}</div><p class="micro">總成本應包括買入成本及相關買入費用。成本未知就留空，唔會當成 0。USD／HKD 損益唔會直接加埋去 MOP 月結。</p>${actions('儲存買賣記錄')}</form>`,f=>{if(f.get('date')>today())throw Error('請填已發生日期。');const n=structuredClone(state),basis=String(f.get('costBasis')).trim(),row={id:old?.id||uid(),date:f.get('date'),side:f.get('side'),symbol:String(f.get('symbol')).trim().toUpperCase(),currency:f.get('currency'),quantity:investmentNumber(f.get('quantity'),'數量'),price:investmentNumber(f.get('price'),'價格'),fees:amount(f.get('fees')),taxes:amount(f.get('taxes')),costBasis:basis===''?null:amount(basis),note:String(f.get('note')).trim()};n.investmentTrades=[...(n.investmentTrades||[]).filter(x=>x.id!==row.id),row];commit(n);$('#modal').close()})}
async function restorePreview(incoming,createdAt,label){validate(incoming);const a=summary(state),b=summary(incoming);modal('預覽還原帳本',`<p>${esc(label)} · ${timeLabel(createdAt)}</p><div class="table-wrap"><table><thead><tr><th>資料</th><th>目前</th><th>備份</th></tr></thead><tbody>${[['transactions','交易'],['goals','儲錢目標'],['holdings','持倉'],['closes','投資月結']].map(([k,n])=>`<tr><td>${n}</td><td>${a[k]}</td><td>${b[k]}</td></tr>`).join('')}</tbody></table></div><p class="small muted">還原會取代帳本，唔會合併；先自動保存目前本機副本。</p><form>${actions('保留副本並還原')}</form>`,async()=>{const raw=localStorage.getItem(KEY);if(storageBroken){if(raw)localStorage.setItem(KEY+'-rescue-'+Date.now(),raw);storageBroken=false;revision=raw}await localCheckpoint(state,'還原前副本');commit(structuredClone(incoming));$('#modal').close();location.hash='home';render();toast('已還原；原帳本可喺本機還原副本搵返。')})}
async function versionsForm(){try{const rows=await localVersions();modal('本機還原副本',`<p class="small muted">最近 10 份還原前副本，清除網站資料會刪除。日常備份請下載 JSON 檔案。</p><div class="settings-list">${rows.map((r,i)=>`<button class="btn" data-version-index="${i}">${timeLabel(r.createdAt)}<br>${r.transactions} 筆交易 · ${r.goals} 個目標${r.label?' · '+esc(r.label):''}</button>`).join('')||'<p>未有副本；還原備份前會先保留目前帳本。</p>'}</div>`);$('#modal-content').querySelectorAll('[data-version-index]').forEach(b=>b.onclick=async()=>{try{const r=rows[+b.dataset.versionIndex];await restorePreview(r.state,r.createdAt,'本機副本')}catch(e){toast(e.message)}})}catch(e){toast(e.message)}}


function upgradeBind(all){all('[data-quick]',()=>quickExpense());all('[data-cash-plan]',cashPlanForm);all('[data-insurance-settings]',insuranceSettings);all('[data-pay-insurance]',payInsuranceForm);all('[data-invest-close]',investmentCloseForm);all('[data-new-trade]',()=>tradeForm());all('[data-trade]',b=>tradeForm(b.dataset.trade));all('[data-local-versions]',versionsForm);all('[data-card-settings]',cardReminderForm);}


function cardReminderForm(){const c=state.settings.cardReminder||{enabled:false,day:10};modal('設定找卡數提醒',`<form>${field('每月日期',input('day',c.day,'number','required min="1" max="31" step="1"'))}<label class="check"><input type="checkbox" name="enabled" ${c.enabled?'checked':''}>啟用 App 內提醒</label><p class="micro">月份冇嗰日會用月底，只喺打開 App 時顯示。請以銀行實際到期日為準。</p>${actions('儲存提醒')}</form>`,f=>{const day=Number(f.get('day'));if(!Number.isInteger(day)||day<1||day>31)throw Error('請填 1 至 31。');const n=structuredClone(state);n.settings.cardReminder={day,enabled:!!f.get('enabled')};commit(n);$('#modal').close()})}
